<?php// teams/models/Team.phpclass Team {    private PDO $pdo;    public function __construct(PDO $pdo) {        $this->pdo = $pdo;    }    /**     * Create a new team - enforces: enrolled in unit, assessment allows teams, etc.     */    public function create(string $title, int $unitId, int $assessmentId): int {        $userId = $_SESSION['user_id'] ?? 0;        if ($_SESSION['role'] !== 'student' || $userId <= 0) {            throw new Exception("Only enrolled students can create teams");        }        // 1. Check student is enrolled in the unit        $stmt = $this->pdo->prepare("            SELECT e.student_id, s.course_id, s.year            FROM enrollments e            JOIN students s ON e.student_id = s.id            WHERE e.unit_id = ? AND e.student_id = ?        ");        $stmt->execute([$unitId, $userId]);        $enrollment = $stmt->fetch(PDO::FETCH_ASSOC);        if (!$enrollment) {            throw new Exception("You are not enrolled in this unit");        }        // 2. Check assignment allows teams        $stmt = $this->pdo->prepare("            SELECT assignment_mode             FROM team_assignments             WHERE id = ?        ");        $stmt->execute([$assessmentId]);        $mode = $stmt->fetchColumn();        if ($mode === 'individual_only') {            throw new Exception("This assignment does not allow team submissions");        }        // 3. Create team        $stmt = $this->pdo->prepare("            INSERT INTO teams             (title, unit_id, assessment_id, created_by, course_id, year, status)            VALUES (?, ?, ?, ?, ?, ?, 'active')        ");        $stmt->execute([            $title,            $unitId,            $assessmentId,            $userId,            $enrollment['course_id'],            $enrollment['year']        ]);        $teamId = (int) $this->pdo->lastInsertId();        // 4. Add creator as leader        $memberModel = new TeamMember($this->pdo);        $memberModel->add($teamId, $userId, 'leader');        return $teamId;    }    public function findById(int $id): ?array {        $stmt = $this->pdo->prepare("SELECT * FROM teams WHERE id = ?");        $stmt->execute([$id]);        return $stmt->fetch(PDO::FETCH_ASSOC) ?: null;    }    public function getTeamsForAssessment(int $assessmentId, int $page = 1, int $perPage = 20): array {        $offset = ($page - 1) * $perPage;        $stmt = $this->pdo->prepare("            SELECT * FROM teams             WHERE assessment_id = ?             ORDER BY created_at DESC             LIMIT ? OFFSET ?        ");        $stmt->execute([$assessmentId, $perPage, $offset]);        return $stmt->fetchAll(PDO::FETCH_ASSOC);    }    // ... more methods as needed (archive, lock, etc.)}